function project ( u0, v0, p, div ) {
  var h = 1.0 / N;
  for ( var i=1 ; i<=N ; i++ ) {
    for ( var j=1 ; j<=N ; j++ ) {
      div[IX(i,j)] = -0.5 * h * ( u0[IX(i+1,j)] - u0[IX(i-1,j)] + v0[IX(i,j+1)] - v0[IX(i,j-1)] );
